    {
      "вещество": "Белки (общее содержание)",
      "содержание": "12–18 % от сухого веса",
      "влияние": "Источники аминокислот; отдельные белки могут вызывать аллергические реакции у чувствительных лиц."
    },
    {
      "вещество": "Липиды (фосфолипиды, стерины – эргостерин)",
      "содержание": "1–3 % от сухого веса",
      "влияние": "Компоненты мембран; эргостерин в организме человека превращается в витамин D₂."
    },
    {
      "вещество": "Свободные аминокислоты (глутаминовая, аспарагиновая, глутамин)",
      "содержание": "~1–3 % от сухого веса",
      "влияние": "Вкусовые и структурные компоненты; в высоких дозах глутамат возбуждает нейроны."
    }
  ]
}

{
