      "вещество": "мусцимола (muscimol)",
      "содержание": "1–5 % от сухого веса",
      "влияние": "Сильный агонист ГАМК-A рецепторов, вызывает угнетение ЦНС, галлюцинации, судороги и кому при передозировке."
    },
    {
      "вещество": "мускарина (muscarine)",
      "содержание": "следовые количества, <0,1 мг/кг",
      "влияние": "Агонист мускариновых холинорецепторов, при высоких дозах вызывает брадикардию и бронхоспазм; в количественных для A. citrina уровнях клинически не значим."
    }
  ]
}

{
  "гриб": "Amanita caesarea (мухомор Цезаря, цезарский гриб)",
  "состав": [
    {
      "вещество": "Вода",
      "содержание": "~90 % от свежего веса",
      "влияние": "Составляющая организма; не оказывает фармакологического действия."
    },
    {
      "вещество": "Протеины (суммарные)",
      "содержание": "3–5 % от свежего веса (≈30–45 % от сухого)",
      "влияние": "Поставляют аминокислоты для синтеза белков организма; грибной белок хорошо усваивается."
    },
    {
      "вещество": "Трегалоза",
      "содержание": "1–3 % от свежего веса",
      "влияние": "Двомерный сахар, в связанном виде входит в хитин-трегалозный комплекс стенки клетки; как пищевой компонент метаболизируется как глюкоза."
    },
    {
      "вещество": "Хитин",
      "содержание": "2–4 % от свежего веса",
      "влияние": "Полисахарид клеточной стенки; у человека частично расщепляется кишечной микрофлорой и стимулирует перистальтику."
    },
    {
      "вещество": "β-D-Глюкан (β-глюкан)",
      "содержание": "1–2 % от свежего веса",
      "влияние": "Растворимый полисахарид; в дозах, содержащихся в съедобном количестве гриба, может умеренно модулировать активность макрофагов."
    },
    {
      "вещество": "Гликоген",
      "содержание": "2–4 % от свежего веса",
      "влияние": "Запасной углевод; после термообработки расщепляется и восполняет энергетические запасы."
    },
    {
      "вещество": "Эргостерол",
      "содержание": "100–400 мг/кг сухого веса",
      "влияние": "При воздействии UV-света превращается в эргокальциферол (витамин D₂), участвующий в обмене кальция."
    },
    {
      "вещество": "Каротиноидные пигменты (оранжево-красная окраска шляпки)",
      "содержание": "следовые, но определяющие цвет (не более ~100 мг/кг сухого веса)",
      "влияние": "Обладают антиоксидантной активностью, нейтрализуя свободные радикалы."
    },
    {
      "вещество": "Ненасыщенные жирные кислоты (линолевая, олеиновая)",
      "содержание": "~1–2 % от свежего веса (липидная фракция)",
      "влияние": "Входят в структуру мембран; в пищевых дозах участвуют в обмене липидов и синтезе эйкозаноидов."
    },
    {
      "вещество": "Нуклеиновые кислоты (ДНК + РНК)",
      "содержание": "0,5–1 % от свежего веса",
      "влияние": "При переваривании расщепляются до пуриновых оснований; у людей с подагрой могут повышать уровень мочевой кислоты."
    },
    {
      "вещество": "Манинит",
      "содержание": "0,3–0,8 % от свежего веса",
      "влияние": "Шестьатомный спирт; слабое мягкое слабящее действие, при пищевых дозах инертен."
    },
    {
      "вещество": "Глюкоза",
      "содержание": "0,5–1,5 % от свежего веса",
      "влияние": "Быстроусвояемый моносахарид, источник энергии."
    },
    {
      "вещество": "Свободные аминокислоты (суммарно)",
      "содержание": "0,3–0,8 % от свежего веса",
      "влияние": "Вносят вклад в вкус (глютамат, аспартат) и участвуют в азотистом обмене."
    },
    {
      "вещество": "Минеральные соли (K, P, Ca, Mg, Fe — суммарно)",
      "содержание": "3–5 % от сухого веса (≈0,3–0,5 % свежего)",
      "влияние": "Обеспечивают электролитный баланс, передачу нервных импульсов и кислородтранспортную функцию (Fe)."
    },
    {
      "вещество": "Аскорбиновая кислота (витамин С)",
      "содержание": "5–20 мг/100 г свежего веса",
      "влияние": "Антиоксидант, софактор синтеза коллагена и усвоения железа."
    }
  ]
}

{
  "гриб": "Amanita virosa (мухомор вонючий)",
  "состав": [
    {
      "вещество": "α-аманитин",
      "содержание": "0,04–0,15 % от сухого веса",
