    {
      "вещество": "фалло-α-токсин (α-phallotoxin)",
      "содержание": "≈0,02–0,05 % от сухого веса",
      "влияние": "Связывается с актиновыми микрофиламенты и нарушает проницаемость клеточных мембран, вызывая цитолитический отёк."
    },
    {
      "вещество": "фалло-β-токсин (β-phallotoxin)",
      "содержание": "≈0,01–0,03 % от сухого веса",
      "влияние": "Диссоциирует актиновые филаменты и повышает проницаемость мембран, усиливая повреждение эпителиальных клеток."
    },
    {
      "вещество": "фалло-γ-токсин (γ-phallotoxin)",
      "содержание": "≈0,005–0,02 % от сухого веса",
      "влияние": "Нарушает цитоскелет и мембранную целостность клеток, особенно выраженное гемолитическое действие."
    },
    {
      "вещество": "фаллоидин",
      "содержание": "≈0,005–0,01 % от сухого веса",
      "влияние": "Стабилизирует F-актин in vitro; in vivo при высоких дозах нарушает клеточную подвижность и деление."
    },
    {
      "вещество": "виоротоксин",
      "содержание": "следовые количества (характерно для A. virosa)",
      "влияние": "Протеолитически нестойкий фаллотоксин, разрушающий мембраны эритроцитов и эпителиальных клеток."
    },
    {
      "вещество": "фальсин",
      "содержание": "≈0,002–0,008 % от сухого веса",
      "влияние": "Фаллотоксин, повышающий проницаемость клеточных мембран и способствующий цитолизму."
    },
    {
      "вещество": "иботеновая кислота",
      "содержание": "≈0,01–0,05 % от сухого веса",
      "влияние": "Необратимый агонист NMDA-рецепторов, вызывающий эксайтотоксическое повреждение нейронов."
    },
    {
      "вещество": "мусцимол",
      "содержание": "≈0,005–0,02 % от сухого веса",
      "влияние": "Агонист ГАМК_A-рецепторов, оказывает седативное и антиконвульсантное действие."
    }
  ]
}

